mapper.update:
update trip_day
set day_no = day_no - 1
where trip_id = #{tripId}
  and day_no > #{dayNo}

mapper.select:
select count(*)
from schedule s
join trip_day d on s.day_id = d.day_id
where d.trip_id = #{tripId}
  and d.day_no > #{dayNo}

mapper.delete:
delete from trip_day
where trip_id = #{tripId}
  and day_no > #{dayNo}

mapper.update:
update trip_day
   set day_no  = day_no + #{count}
 where trip_id = #{tripId}
   and day_no  > #{position}
